def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    me = [h[0] for h in history]
    op = [h[1] for h in history]
    op_c = op.count('C')
    op_d = n - op_c
    my_c = me.count('C')
    my_d = n - my_c
    last_op = op[-1]
    last_me = me[-1]

    # Always-defect opponent: defect.
    if op_c == 0:
        return 'D'

    # Always-cooperate opponent: exploit late, build trust early.
    if op_d == 0:
        if n < 90:
            return 'C'
        return 'D'

    # Remaining rounds
    remaining = 100 - n

    # Recent window stats (last 12)
    w = history[-12:]
    wlen = len(w)
    w_op_c = sum(1 for _, b in w if b == 'C')
    w_op_d = wlen - w_op_c
    w_me_c = sum(1 for a, _ in w if a == 'C')

    # Count consecutive opponent defections/cooperations at tail.
    streak_d = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            streak_d += 1
        else:
            break
    streak_c = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            streak_c += 1
        else:
            break

    # Detect opponent mimicry (TFT-like): does op play our previous action?
    if n >= 6:
        mimic = 0
        for i in range(1, n):
            if op[i] == me[i - 1]:
                mimic += 1
        if mimic >= n - 2:
            # Opponent mirrors us. Cooperate for mutual gain most of the time;
            # exploit occasionally near the end.
            if remaining <= 2:
                return 'D'
            if last_op == 'D':
                return 'C'
            # Occasional single-round defection to try for 5, then apologize.
            if n > 5 and n % 15 == 0 and streak_c >= 2:
                return 'D'
            return 'C'

    # Detect grim-trigger: after our first D, they defected forever.
    if my_d >= 1:
        first_d = -1
        for i in range(n):
            if me[i] == 'D':
                first_d = i
                break
        if first_d >= 0 and first_d < n - 1:
            tail_ok = True
            cnt = 0
            for i in range(first_d + 1, n):
                cnt += 1
                if op[i] != 'D':
                    tail_ok = False
                    break
            if tail_ok and cnt >= 3:
                # Locked into DD. Occasionally try C to see if they forgive.
                if remaining > 3 and rng.random() < 0.1:
                    return 'C'
                return 'D'

    # If opponent is heavily defecting overall, mirror/defect.
    if op_d * 2 >= n and op_d > op_c:
        # If they've just cooperated once after a long D streak, reward lightly.
        if last_op == 'C' and streak_c >= 1 and streak_d >= 2 and remaining > 5:
            return 'C'
        return 'D'

    # Endgame: exploit known cooperators.
    if remaining <= 1:
        # Last round: if opponent likely cooperates (high recent coop rate), defect.
        if op_c * 4 >= n * 3:
            return 'D'
        if last_op == 'D':
            return 'D'
        return 'C'

    if remaining <= 4:
        if op_c * 5 >= n * 4:
            return 'D'
        if last_op == 'D' and streak_d >= 2:
            return 'D'
        return 'C'

    if remaining <= 10:
        if op_c * 3 >= n * 2 and last_op == 'C':
            return 'D'
        if streak_d >= 2:
            return 'D'
        if last_op == 'C':
            return 'C'
        return 'D'

    # Mid-game: TFT with forgiveness, avoiding endless DD loops.
    if last_op == 'D':
        # If we also defected last round, try to break the mutual-DD cycle.
        if last_me == 'D':
            if streak_d >= 3:
                # Persistent: defect but occasionally attempt reconciliation.
                if remaining > 10 and rng.random() < 0.08:
                    return 'C'
                return 'D'
            # Just mutual DD once or twice: try C to restore cooperation.
            if op_c * 3 >= n:
                return 'C'
            return 'D'
        # We cooperated, they defected: retaliate.
        if streak_d >= 3:
            return 'D'
        if op_d * 4 > n * 3:
            return 'D'
        # Single recent defection from a mostly-cooperative opponent:
        # retaliate lightly then forgive.
        if w_op_c * 3 >= wlen * 2:
            return 'D'
        return 'D'

    # Opponent just cooperated.
    if last_me == 'D':
        # We defected and they still cooperated: they're forgiving. Cooperate back,
        # but occasionally re-exploit while they remain forgiving.
        if op_c * 5 >= n * 4:
            # Mostly cooperative and forgiving - probe occasionally.
            if n % 11 == 0 and remaining > 12:
                return 'D'
            return 'C'
        return 'C'

    # Both cooperated last round. Stay in cooperation.
    if op_c * 4 >= n * 3:
        # Opponent is nice: occasionally probe mid-game.
        if n > 15 and n % 19 == 0 and streak_c >= 3 and remaining > 12:
            return 'D'
        return 'C'

    # Mixed opponent: cooperate unless recent behavior is bad.
    if w_op_d * 3 > wlen:
        return 'D'
    return 'C'
